(function(){const G = window.__game, A = G.Air.s, K = G.Keys, TH = G.THREE_, id = 'wren';
G.save.set.dev = true; G.save.set.cycle = 0; G.Dev.god = true; G.save.air.own[id] = true; G.Fly.tags();
const msgs = []; const ot = G.UI.toast, ob = G.UI.banner; G.UI.toast = (t, k) => { msgs.push('T:' + t); }; G.UI.banner = (k, t) => { msgs.push('B:' + k + ' ' + t); };
G.UI.devAct('tpair'); for (let i = 0; i < 40; i++) G.Chunks.update(A.cx - 150, A.cz + 60, 3);
G.Foot.exit();
const P = G.Fly.planes.find(p => p.id === id);
G.Foot.x = P.x + 3.0; G.Foot.z = P.z; G.Foot.y = P.y - P.spec.cgY; G.Fly.scan();
if (!G.Fly.near) return 'no near: ' + G.Foot.on;
G.Fly.useNear();
const rw = G.AIR.RW, S = P.spec, d0 = 700, V0 = S.Vs * 1.35;
P.x = A.cx + rw.u0 - d0; P.z = A.cz + 0; P.y = A.H0 + d0 * 0.0524 + S.cgY + 2; P.thr = 0.4;
P.q.setFromEuler(new TH.Euler(0.03, Math.PI / 2, 0, 'YXZ')); P.vx = V0; P.vy = -V0 * 0.0524; P.vz = 0; P.airT = 30;
for (let i = 0; i < 30; i++) G.Chunks.update(P.x, P.z, 3);
const dt = 1 / 60, rows = []; let t = 0, touched = -1;
const dg = (r) => (r / Math.PI * 180).toFixed(1);
for (let i = 0; i < 60 * 70; i++) {
  const agl = P.agl === undefined ? 20 : P.agl, V = P.speed || V0, vy = P.vy;
  let vs = -V * 0.0524; if (agl < 9) vs = -0.45 - agl * 0.1; if (agl < 3.5) vs = -0.2;
  K.KeyS = false; K.KeyW = false; K.ShiftLeft = false; K.KeyZ = false; K.Space = false; K.KeyD = false; K.KeyA = false;
  if (!P.gnd) {
    if (vy < vs - 0.3) K.KeyS = true; else if (vy > vs + 0.3) K.KeyW = true;
    if (agl < 8) { K.KeyZ = true; } else if (V < S.Vs * 1.32) K.ShiftLeft = true; else if (V > S.Vs * 1.5) K.KeyZ = true;
    const dz = P.z - (A.cz + 0); if (dz > 3) K.KeyA = true; else if (dz < -3) K.KeyD = true;
  } else { K.KeyZ = true; if (touched < 0) touched = t; if (V < 20) K.Space = true; }
  G.stepSim(dt); t += dt;
  if (i % 30 === 0 || (P.gnd && touched >= 0 && t - touched < 0.2)) rows.push([t.toFixed(1), (V * 3.6).toFixed(0), agl.toFixed(1), vy.toFixed(2), dg(P.pitch), dg(P.bank), P.thr.toFixed(2), P.gnd ? 'G' : 'A', P.st, ((P.x - A.cx)).toFixed(0), ((P.z - A.cz)).toFixed(0)].join(' '));
  if (P.st === 'wreck') { rows.push('WRECK ' + G.Fly.why); break; }
  if (touched >= 0 && t - touched > 14 && P.speed < 1) break;
}
K.KeyS = K.KeyW = K.ShiftLeft = K.KeyZ = K.Space = K.KeyA = K.KeyD = false;
return rows.join('\n') + '\n' + msgs.join('\n') + '\nmoney ' + G.save.money + ' ldg ' + G.save.air.ldg + ' best ' + G.save.air.best;})()
